const centerLon=(b[0]+b[2])/2,centerLat=(b[1]+b[3])/2,lonKm=111.32*Math.cos(centerLat*Math.PI/180),latKm=111.32;
function project(lon,lat,alt){let x=(lon-centerLon)*lonKm,y=(lat-centerLat)*latKm,xx=x*Math.cos(angle)-y*Math.sin(angle),yy=x*Math.sin(angle)+y*Math.cos(angle),scale=52*zoom;return [550+xx*scale,350-yy*scale*.49-alt/1000*5*scale]}
