function draw(){if(region!=='zhenlong'||!canvas.isConnected)return;ctx.clearRect(0,0,1100,610);ctx.fillStyle='#e5ebe2';ctx.fillRect(0,0,1100,610);let grid=terrain.values,w=terrain.width,h=terrain.height,patches=[];for(let y=0;y<h-1;y++)for(let x=0;x<w-1;x++){let lon=b[0]+(b[2]-b[0])*x/(w-1),lat=b[3]-(b[3]-b[1])*y/(h-1),lon2=b[0]+(b[2]-b[0])*(x+1)/(w-1),lat2=b[3]-(b[3]-b[1])*(y+1)/(h-1),z=grid[y][x],q=[[lon,lat,z],[lon2,lat,grid[y][x+1]],[lon2,lat2,grid[y+1][x+1]],[lon,lat2,grid[y+1][x]]].map(p=>project(...p));patches.push({q,z,depth:q.reduce((s,p)=>s+p[1],0)/4})}patches.sort((a,b)=>a.depth-b.depth);for(let p of patches){let v=Math.max(0,Math.min(1,(p.z-100)/650));ctx.fillStyle=`rgb(${Math.round(201-40*v)},${Math.round(216-42*v)},${Math.round(199-43*v)})`;ctx.beginPath();p.q.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fill()}
data.trips.forEach((f,i)=>{if(i!==selected)strokeLine(vertices(f),'rgba(61,92,80,.12)',1)});let path=vertices(data.trips[selected]);strokeLine(path,'rgba(255,255,255,.95)',10);strokeLine(path,'#cf5936',5);arrows(data.trips[selected]);
Object.values(nodes).forEach(n=>{let p=project(n.lon,n.lat,n.workAlt),hub=n.id==='O01',stop=data.trips[selected].plan.route.includes(n.id);ctx.beginPath();ctx.arc(p[0],p[1],hub?9:stop?8:6,0,Math.PI*2);ctx.fillStyle=hub?'#df7e48':stop?'#c75d3c':'#194f3d';ctx.fill();ctx.lineWidth=3;ctx.strokeStyle='#fff';ctx.stroke();ctx.font='bold 20px sans-serif';ctx.lineWidth=5;ctx.strokeStyle='#fffdf8';ctx.strokeText(n.id,p[0]+8,p[1]-9);ctx.fillStyle='#243c31';ctx.fillText(n.id,p[0]+8,p[1]-9)});
data.relay.forEach(m=>{let c=m.candidate,p=project(c.longitude,c.latitude,c.altitude_m),ground=project(c.longitude,c.latitude,c.ground_altitude_m),active=time>=m.link_ready_s&&time<=m.service_end_s;ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(...ground);ctx.lineTo(...p);ctx.strokeStyle=active?'#ad6c2e':'#a3ada3';ctx.lineWidth=1.5;ctx.stroke();ctx.setLineDash([]);ctx.save();ctx.translate(...p);ctx.rotate(Math.PI/4);ctx.fillStyle=active?'#d18a40':'#fffdf8';ctx.strokeStyle='#b67932';ctx.fillRect(-5,-5,10,10);ctx.strokeRect(-5,-5,10,10);ctx.restore()});
data.trips.forEach((f,i)=>{let pos=position(f,time);if(!pos)return;let p=project(...pos);ctx.beginPath();ctx.arc(p[0],p[1],i===selected?7:4.5,0,Math.PI*2);ctx.fillStyle=i===selected?'#e47748':'#327b9b';ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=2;ctx.stroke();ctx.font='bold 11px sans-serif';ctx.fillStyle='#153d39';ctx.fillText(f.drone_id,p[0]+7,p[1]-7)});
}
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,angle};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){angle=drag.angle+(e.clientX-drag.x)*.008;draw()}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);$('zl-zoom-in').onclick=()=>{zoom=Math.min(1.6,zoom*1.2);draw()};$('zl-zoom-out').onclick=()=>{zoom=Math.max(.65,zoom/1.2);draw()};$('zl-reset').onclick=()=>{angle=-.47;zoom=1;draw()};
$('zl-time').addEventListener('input',e=>{time=Number(e.target.value)/1000*data.stats.makespan;playing=false;renderText();draw()});$('zl-play').onclick=()=>{if(time>=data.stats.makespan)time=0;playing=!playing;last=0;renderText();if(playing)requestAnimationFrame(tick)};function tick(ts){if(!playing)return;if(last)time=Math.min(data.stats.makespan,time+(ts-last)/1000*120);last=ts;$('zl-time').value=String(Math.round(time/data.stats.makespan*1000));$('zl-clock').textContent=clock(time);draw();if(time>=data.stats.makespan){playing=false;renderText()}else requestAnimationFrame(tick)}
